def health_check() -> dict:
    """
    返回服务健康状态。
    """
    return {
        "status": "ok",
        "service": "test-project",
    }

def get_project_info() -> dict:
    """
    返回测试项目的基础信息。
    """
    return {
        "name": "test-project",
        "version": "0.1.0",
    }

def create_document_api(document_id: str, content: str) -> dict:
    """
    模拟创建文档接口，内部调用 save_document。
    """
    return save_document(
        document_id=document_id,
        content=content,
    )

def list_chunks_api(document_id: str) -> dict:
    """
    模拟查询 chunks 接口，返回指定文档的 chunk 列表。
    """
    return {
        "document_id": document_id,
        "chunks": list_chunks(document_id),
    }

def startup() -> dict:
    """
    启动 API 服务前初始化数据库。
    """
    return init_database()

def get_runtime_config() -> dict:
    """
    返回测试项目运行时配置，供启动流程和 API 模块使用。
    """
    return {
        "database_path": DEFAULT_DATABASE_PATH,
        "log_level": DEFAULT_LOG_LEVEL,
        "top_k": DEFAULT_TOP_K,
    }

def init_database(database_path: str = DEFAULT_DATABASE_PATH) -> dict:
    """
    初始化数据库，并返回创建的表信息。
    """
    tables = [
        "projects",
        "documents",
        "chunks",
    ]

    return {
        "database_path": database_path,
        "tables": tables,
    }

def save_document(document_id: str, content: str) -> dict:
    """
    保存文档内容，返回一条模拟的文档记录。
    """
    return {
        "document_id": document_id,
        "content": content,
        "length": len(content),
    }

def list_chunks(document_id: str) -> list[dict]:
    """
    查询指定文档下的 chunks。
    """
    return [
        {
            "chunk_id": f"{document_id}::chunk_0",
            "document_id": document_id,
            "content": "这是一个示例 chunk。",
        }
    ]

